const channels = [
  { channelId: 'UCbmNph6atAoGfqLoCL_duAg', name: 'Anthropic' },
  { channelId: 'UCXZCJLdBC09xxGZ6gcdrc6A', name: 'OpenAI' },
  { channelId: 'UCP4bf6IHJJQehibu6ai__cg', name: 'Google DeepMind' },
  { channelId: 'UCJXGnMHMSqCaqMzLo8xs6mw', name: 'AI Explained' },
  { channelId: 'UCNJ1Ymd5yFuUPtn21xtRbbw', name: 'Matt Wolfe' }
];
const oneHourAgo = new Date(Date.now() - 60 * 60 * 1000).toISOString();
return channels.map(ch => ({ json: { channelId: ch.channelId, channelName: ch.name, publishedAfter: oneHourAgo } }));

const processedIds = $getWorkflowStaticData('global').processedVideoIds || [];
const items = $json.items || [];
const channelName = $('YouTubeチャンネル設定').item.json.channelName;
const newItems = [];
for (const item of items) {
  const videoId = item.id?.videoId;
  if (!videoId || processedIds.includes(videoId)) continue;
  newItems.push({ json: {
    videoId,
    title: item.snippet?.title || 'タイトルなし',
    channelTitle: item.snippet?.channelTitle || channelName,
    description: (item.snippet?.description || '').slice(0, 500),
    publishedAt: item.snippet?.publishedAt || '',
    videoUrl: `https://www.youtube.com/watch?v=${videoId}`,
    thumbnailUrl: item.snippet?.thumbnails?.high?.url || ''
  } });
}
const allIds = [...processedIds, ...newItems.map(i => i.json.videoId)];
$getWorkflowStaticData('global').processedVideoIds = allIds.slice(-200);
return newItems.length > 0 ? newItems : [{ json: { skip: true } }];

const GITHUB_TOKEN = $env.GITHUB_TOKEN || '';
const BASE = 'https://api.github.com/repos/liquitex-coder/ai-solution-/contents/n8n/prompts/';
const headers = { 'Accept': 'application/vnd.github.v3+json', 'User-Agent': 'n8n-ai-navi/1.0' };
if (GITHUB_TOKEN) headers['Authorization'] = `token ${GITHUB_TOKEN}`;
async function fetchPrompt(file) {
  try {
    const res = await fetch(BASE + file, { headers });
    if (!res.ok) return '';
    const data = await res.json();
    return Buffer.from((data.content || '').replace(/\n/g, ''), 'base64').toString('utf8');
  } catch(e) { return ''; }
}
const [copyright, wfPrompt] = await Promise.all([
  fetchPrompt('00-copyright-transform.md'),
  fetchPrompt('03-youtube-summary.md')
]);
return [{ json: { ...$json, promptContent: copyright + '\n\n---\n\n' + wfPrompt } }];

const content = $json.content[0].text;
const videoData = $('新動画フィルタリング').item.json;
return [{ json: { title: `【YouTube要約】${videoData.title} - ${videoData.channelTitle}`, content, wp_status: 'draft', source_url: videoData.videoUrl || '' } }];

// Auditor Gate — staged rollout (requirements §22-3, INV-R2)
// CLAIM_AUDITOR_MODE: report_only (default) | canary (~10% publish) | full
const auditorUrl = $env.CLAIM_AUDITOR_URL || '';
const mode = ($env.CLAIM_AUDITOR_MODE || 'report_only').toLowerCase();
const content = $json.content || '';
const sourceUrl = $json.source_url || '';
function decide(verdict) {
  if (verdict !== 'PASS') return 'draft';
  if (mode === 'full') return 'publish';
  if (mode === 'canary') {
    const t = ($json.title || '') + String(content.length);
    let h = 0;
    for (let i = 0; i < t.length; i++) h = (h * 31 + t.charCodeAt(i)) >>> 0;
    return (h % 10 === 0) ? 'publish' : 'draft';
  }
  return 'draft'; // report_only: record verdict, never auto-publish
}
if (!auditorUrl) {
  return [{ json: { ...$json, verdict: 'SKIP', audit_mode: mode, wp_status: 'draft',
    audit_note: 'CLAIM_AUDITOR_URL未設定 → 下書き保存' } }];
}
try {
  const res = await fetch(`${auditorUrl}/audit`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      content,
      source_urls: sourceUrl ? [sourceUrl] : [],
      skill_ref: '03-youtube-summary'
    })
  });
  if (!res.ok) {
    return [{ json: { ...$json, verdict: 'UNVERIFIABLE', audit_mode: mode, wp_status: 'draft',
      audit_note: `Auditor HTTP ${res.status}` } }];
  }
  const result = await res.json();
  return [{ json: { ...$json, ...result, audit_mode: mode,
    wp_status: decide(result.verdict) } }];
} catch(e) {
  return [{ json: { ...$json, verdict: 'UNVERIFIABLE', audit_mode: mode, wp_status: 'draft',
    audit_note: e.message } }];
}
